<template><view v-if="show" class="drawer-mask" @click.self="$emit('close')"><view class="detail-drawer" :style="{maxWidth:width}"><view class="drawer-head"><view><text class="drawer-eyebrow">详情</text><text class="drawer-title">{{ title }}</text></view><button class="drawer-close" aria-label="关闭" @click="$emit('close')">×</button></view><scroll-view scroll-y class="drawer-body"><slot /></scroll-view><view v-if="$slots.footer" class="drawer-footer"><slot name="footer" /></view></view></view></template>
<script setup>defineProps({ show:Boolean,title:{type:String,default:'详情'},width:{type:String,default:'640px'} }); defineEmits(['close']);</script>
<style scoped>.drawer-mask{position:fixed;inset:0;z-index:80;display:flex;justify-content:flex-end;background:rgba(15,23,42,.48);backdrop-filter:blur(2px)}.detail-drawer{width:92vw;height:100%;display:flex;flex-direction:column;background:#fff;box-shadow:var(--es-shadow-lg)}.drawer-head{height:72px;flex:none;padding:0 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--es-border-soft)}.drawer-eyebrow,.drawer-title{display:block}.drawer-eyebrow{color:var(--es-primary);font-size:10px;font-weight:700;letter-spacing:.1em}.drawer-title{margin-top:3px;color:var(--es-text);font-size:18px;font-weight:700}.drawer-close{width:34px;height:34px;margin:0;padding:0;color:var(--es-text-dim);font-size:25px;line-height:32px;background:#f8fafc;border:1px solid var(--es-border-soft);border-radius:8px}.drawer-body{min-height:0;flex:1;padding:22px}.drawer-footer{padding:14px 22px;border-top:1px solid var(--es-border-soft)}</style>
